package com.theone.cinema.tv;
import android.content.*;import android.view.KeyEvent;import android.widget.GridView;import androidx.test.core.app.ActivityScenario;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import org.junit.*;import org.junit.runner.RunWith;import java.util.concurrent.atomic.AtomicBoolean;import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class) public class CinemaTvRemoteTest {
 @Test public void remoteBrowsesPlaysPausesAndChoosesLanguage()throws Exception{android.content.Context context=InstrumentationRegistry.getInstrumentation().getTargetContext();assertTrue(context.getPackageManager().hasSystemFeature("android.software.leanback"));context.getSharedPreferences("the_one_cinema_tv",0).edit().putString("preferred_language","en").commit();UiDevice device=UiDevice.getInstance(InstrumentationRegistry.getInstrumentation());Intent i=new Intent(context,MainActivity.class);i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK);i.putExtra("cinema_test_mode",true);try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(i)){
 assertTrue(device.wait(Until.hasObject(By.textContains("THE ONE CINEMA")),10000));AtomicBoolean backgroundCancelled=new AtomicBoolean(false);scenario.onActivity(a->{try{a.registerBackgroundForTest(()->backgroundCancelled.set(true));}catch(java.io.IOException e){throw new RuntimeException(e);}GridView grid=a.findViewById(1020);grid.requestFocus();grid.setSelection(0);});device.pressDPadRight();device.pressDPadCenter();assertTrue(device.wait(Until.hasObject(By.text("▶ Kijk")),5000));device.pressDPadCenter();AtomicBoolean ready=new AtomicBoolean(false);for(int n=0;n<40&&!ready.get();n++){scenario.onActivity(a->ready.set(a.isPlaybackReadyForTest()));Thread.sleep(250);}assertTrue("TV native player renders video",ready.get());assertTrue("Playing cancels an active background request",backgroundCancelled.get());scenario.onActivity(a->assertTrue("Background network is suspended during playback",a.isBackgroundPausedForTest()));device.pressKeyCode(KeyEvent.KEYCODE_MEDIA_PAUSE);Thread.sleep(300);scenario.onActivity(a->ready.set(a.isPlaybackReadyForTest()));assertFalse("Remote pauses video",ready.get());device.pressKeyCode(KeyEvent.KEYCODE_MEDIA_PLAY);Thread.sleep(500);scenario.onActivity(a->ready.set(a.isPlaybackReadyForTest()));assertTrue("Remote resumes video",ready.get());device.pressBack();device.waitForIdle();scenario.onActivity(a->assertFalse("Returning to catalog resumes background work",a.isBackgroundPausedForTest()));scenario.onActivity(a->{GridView grid=a.findViewById(1020);grid.requestFocus();grid.setSelection(0);});device.pressDPadUp();device.pressDPadUp();device.pressDPadRight();device.pressDPadCenter();assertTrue("Remote opens language menu",device.wait(Until.hasObject(By.text("Taalvoorkeur")),5000));device.pressDPadDown();device.pressDPadCenter();assertTrue(device.wait(Until.hasObject(By.text("Cinema testfilm 1 NL")),5000));assertEquals("nl",context.getSharedPreferences("the_one_cinema_tv",0).getString("preferred_language",""));
 }finally{context.getSharedPreferences("the_one_cinema_tv",0).edit().putString("preferred_language","en").commit();}}
 @Test public void relayHeaderIsScopedToOwnerRelay()throws Exception{MediaRepository r=new MediaRepository(InstrumentationRegistry.getInstrumentation().getTargetContext());assertTrue(r.headersForUri("http://cqqwnnig.bulidns.com/movie/test").isEmpty());assertEquals(1,r.headersForUri("https://rubenvanaggelen.com/the-one-remote-api/cinema.php?action=stream").size());}
}
